package com.example

import com.example.ExamQuestionHelper.QSpec
import com.example.ExamQuestionHelper.buildPoolFromShortAnswers
import com.example.ExamQuestionHelper.buildPoolFromSubjectMaster
import com.example.ExamQuestionHelper.dedupPool
import com.example.ExamQuestionHelper.quizQuestionToSpec
import com.example.ExamQuestionHelper.selectFromMasterPool

/**
 * Curated Buddhism O/L Question Pool (Grades 10 & 11).
 * Combines QuizBankBuddhism (100), curated Tripitaka/Sutta/Councils/Buddhacharitha/Heritage MCQs (180+),
 * SubjectMasterBuddhism (1,580+ multi-angle), and ShortAnswer Buddhism (400 G10+G11).
 */
object BuddhismMockPoolHelper {

  private val pool: List<QSpec> by lazy { buildMasterPool() }

  fun getQuestion(grade: String, term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    return selectFromMasterPool(pool, grade, term, paperIdx, qNum)
  }

  private fun buildMasterPool(): List<QSpec> {
    val raw = ArrayList<QSpec>(2600)

    // 1. 100 Curated QuizBankBuddhism MCQs
    for (setIdx in 1..10) {
      for (qIdx in 1..10) {
        val qq = QuizBankBuddhism.getQuestion("10", setIdx, qIdx, qIdx, "බුද්ධ ධර්මය")
        raw.add(quizQuestionToSpec("බුද්ධ ධර්මය - ඒකකය $setIdx", qq))
      }
    }

    // 2. Curated Dhamma, Sutta, Vinaya, Shasana History & Sri Lankan Buddhist Culture MCQs
    raw.addAll(buildCuratedBuddhismFacts())

    // 3. SubjectMasterRepository Buddhism multi-angle pool (~1,580 specs)
    raw.addAll(
      buildPoolFromSubjectMaster(
        categories = SubjectMasterRepository.getCategoriesForSubject("බුද්ධ ධර්මය"),
        subjectLabel = "බුද්ධ ධර්මය",
        seedBase = 43
      )
    )

    // 4. ShortAnswerMasterRepository Grade 10 & Grade 11 Buddhism (~400 specs)
    raw.addAll(buildPoolFromShortAnswers("බුද්ධ ධර්මය"))

    return dedupPool(raw)
  }

